#[cfg(test)]
mod chain_probe {
    use gpui_kit::component::Root;
    use gpui_kit::{AppContext as _, TestAppContext};

    use super::ChatInput;

    #[gpui_kit::test]
    fn probe_chain_bottom(cx: &mut TestAppContext) {
        cx.update(|cx| {
            gpui_kit::init(cx);
            crate::theme::init(cx);
            gpui_kit::component::Theme::change(gpui_kit::component::ThemeMode::Dark, None, cx);
            super::bind_keys(cx);
            crate::piton_syntax::init();
            crate::project_directory::ProjectDirectory::init(cx);
        });
        let mut input = None;
        let window = cx.add_window(|window, cx| {
            let view = cx.new(|cx| ChatInput::new(window, cx));
            input = Some(view.clone());
            Root::new(view, window, cx)
        });
        let input = input.unwrap();
        let handle = window.into();
        for tab in 0..4 {
            cx.update_window(handle, |_, window, cx| {
                input.update(cx, |input, cx| input.select_tab(tab, window, cx));
            })
            .unwrap();
            for _ in 0..40 {
                std::thread::sleep(std::time::Duration::from_millis(25));
                cx.update_window(handle, |_, window, cx| window.render_frame(cx)).unwrap();
            }
            cx.update_window(handle, |_, window, cx| {
                window.render_frame(cx);
                let [_, chain, _, _] = super::tests::tab_layout(window, cx);
                let scale = window.scale_factor();
                let (x0, x1) = (chain.left().as_f32() * scale, chain.right().as_f32() * scale);
                let bottom = chain.bottom().as_f32() * scale;
                eprintln!("PROBE tab {tab} chain {chain:?}");
                for q in window.painted_quads() {
                    let b = &q.bounds;
                    let w = &q.border_widths;
                    let m = &q.content_mask.bounds;
                    // Horizontal lines near the chain's bottom that overlap it.
                    let overlaps = b.origin.x.0 < x1 && b.origin.x.0 + b.size.width.0 > x0 && m.origin.x.0 < x1 && m.origin.x.0 + m.size.width.0 > x0;
                    if !overlaps { continue; }
                    let fill_line = b.size.height.0 <= 2.5 && (b.origin.y.0 - bottom).abs() < 6.;
                    let border_line = w.bottom.0 > 0. && (b.origin.y.0 + b.size.height.0 - bottom).abs() < 6.;
                    let top_line = w.top.0 > 0. && (b.origin.y.0 - bottom).abs() < 6.;
                    if (fill_line || border_line || top_line) && (q.border_color.a > 0. || q.background.as_solid().is_some_and(|c| c.a > 0.)) {
                        let vis_top = m.origin.y.0.max(b.origin.y.0 + b.size.height.0 - w.bottom.0);
                        let vis_bottom = (m.origin.y.0 + m.size.height.0).min(b.origin.y.0 + b.size.height.0);
                        eprintln!("PROBE   {b:?} b{} t{} bc {:?} bg {:?} mask {m:?} bottom-visible {}", w.bottom.0, w.top.0, q.border_color, q.background.as_solid(), vis_bottom > vis_top);
                    }
                }
                crate::frame_image::save(window, std::path::Path::new(&format!("/tmp/chain{tab}.ppm")));
            })
            .unwrap();
        }
    }
}
